package studio.solocamera;
import android.app.*;import android.content.*;import android.graphics.*;import android.net.Uri;import android.os.*;import android.text.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;
/** Focused creator dialogs; tools remain separate from the camera workspace. */
final class EditorCreatorTools {
 private final EditorActivity a;private final EditorCreatorStore store;
 EditorCreatorTools(EditorActivity a){this.a=a;store=new EditorCreatorStore(a);}
 private int dp(int v){return Math.round(v*a.getResources().getDisplayMetrics().density);}
 private LinearLayout column(){LinearLayout p=new LinearLayout(a);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(dp(12),dp(6),dp(12),dp(8));p.setBackgroundColor(0xff10161f);return p;}
 private TextView label(String text){TextView v=new TextView(a);v.setText(text);v.setTextColor(-1);v.setTextSize(14);v.setPadding(0,dp(9),0,dp(5));return v;}
 private Button button(String text,Runnable action){Button b=new Button(a);b.setText(text);b.setOnClickListener(v->action.run());return b;}
 private AlertDialog show(String title,LinearLayout content){ScrollView scroll=new ScrollView(a);scroll.addView(content);AlertDialog d=new AlertDialog.Builder(a).setTitle(title).setView(scroll).setPositiveButton("Done",null).create();d.show();return d;}
 private EditText field(LinearLayout p,String name,String value,int max){p.addView(label(name));EditText e=new EditText(a);e.setTextColor(-1);e.setText(value);e.setContentDescription(name);e.setFilters(new InputFilter[]{new InputFilter.LengthFilter(max)});p.addView(e);return e;}
 private Spinner select(LinearLayout p,String name,String[] values,int selected){p.addView(label(name));Spinner s=new Spinner(a);s.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,values));s.setSelection(selected);s.setContentDescription(name);p.addView(s);return s;}
 private void colors(LinearLayout p,String name,int selected,java.util.function.IntConsumer changed){p.addView(label(name));LinearLayout row=new LinearLayout(a);for(int c:new int[]{0xffffffff,0xff121e2b,0xffffc857,0xff66d4e2,0xff8fafff,0xffff8b79,0xff7ee2bc,0xffc5a4ff}){Button b=button("",()->changed.accept(c));b.setContentDescription(name+" "+Integer.toHexString(c));b.setMinWidth(0);b.setMinimumWidth(0);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(c));row.addView(b,new LinearLayout.LayoutParams(0,dp(36),1));}p.addView(row);}
 void brand(){JSONObject b=store.brand();LinearLayout p=column();p.addView(label("Save your identity once. New library designs use it automatically; existing projects change only when you apply it."));Switch enabled=new Switch(a);enabled.setText("Use brand kit for new designs");enabled.setTextColor(-1);enabled.setChecked(b.optBoolean("enabled"));p.addView(enabled);EditText name=field(p,"Creator / business name",b.optString("name","Your name"),100),role=field(p,"Role / tagline",b.optString("role","Creator & presenter"),150),handle=field(p,"Social handle",b.optString("handle","@yourhandle"),100);ArrayList<String> names=new ArrayList<>(Arrays.asList("Inter","Montserrat","Poppins","Bebas Neue","Playfair Display","Lora")),values=new ArrayList<>(Arrays.asList("font:inter","font:montserrat","font:poppins","font:bebasneue","font:playfairdisplay","font:lora"));EditorFontLibrary.appendInstalled(a,names,values);Spinner fonts=select(p,"Brand font",names.toArray(new String[0]),Math.max(0,values.indexOf(b.optString("font","font:inter"))));int[] palette={b.optInt("accent",0xffffc857),b.optInt("background",0xff121e2b),b.optInt("textColor",-1)};colors(p,"Brand accent",palette[0],v->palette[0]=v);colors(p,"Brand background",palette[1],v->palette[1]=v);colors(p,"Brand text",palette[2],v->palette[2]=v);p.addView(label(b.optString("logo").isEmpty()?"No logo selected":"Logo saved on this phone"));
 AlertDialog dialog=show("My brand kit",p);Runnable save=()->{try{b.put("enabled",enabled.isChecked()).put("name",name.getText().toString()).put("role",role.getText().toString()).put("handle",handle.getText().toString()).put("font",values.get(fonts.getSelectedItemPosition())).put("accent",palette[0]).put("background",palette[1]).put("textColor",palette[2]);store.brand(b);}catch(JSONException ignored){}};dialog.setOnDismissListener(d->save.run());p.addView(button("Choose logo",()->{save.run();dialog.dismiss();a.creatorPick(560,"image/*");}));if(!b.optString("logo").isEmpty())p.addView(button("Remove logo",()->{try{b.put("logo","");store.brand(b);}catch(JSONException ignored){}dialog.dismiss();brand();}));p.addView(button("Apply kit to selected text",()->{save.run();EditorProject.Clip c=a.creatorSelectedText();if(c==null){toast("Select a text layer first");return;}a.creatorCheckpoint();store.applyBrand(c,true);a.creatorChanged();toast("Brand applied to selected text");}));}
 void logo(Uri uri){ProgressDialog progress=ProgressDialog.show(a,"Saving logo","Preparing a small local copy…",true,false);new Thread(()->{String error="";File file=null;try{BitmapFactory.Options opts=new BitmapFactory.Options();opts.inJustDecodeBounds=true;try(InputStream in=a.getContentResolver().openInputStream(uri)){BitmapFactory.decodeStream(in,null,opts);}if(opts.outWidth<1||opts.outHeight<1)throw new IOException("Choose a readable PNG, JPEG or WebP image");opts.inSampleSize=1;while(opts.outWidth/opts.inSampleSize>1024||opts.outHeight/opts.inSampleSize>1024)opts.inSampleSize*=2;opts.inJustDecodeBounds=false;Bitmap bitmap;try(InputStream in=a.getContentResolver().openInputStream(uri)){bitmap=BitmapFactory.decodeStream(in,null,opts);}if(bitmap==null)throw new IOException("Cannot read image");File dir=new File(a.getFilesDir(),"creator-assets");if(!dir.exists()&&!dir.mkdirs())throw new IOException("Cannot create logo storage");file=new File(dir,"logo-"+UUID.randomUUID()+".png");try(FileOutputStream out=new FileOutputStream(file)){if(!bitmap.compress(Bitmap.CompressFormat.PNG,100,out))throw new IOException("Cannot save logo");}finally{bitmap.recycle();}JSONObject b=store.brand();b.put("logo",file.getAbsolutePath());store.brand(b);}catch(Exception e){error=e.getMessage();if(file!=null)file.delete();}String message=error;a.runOnUiThread(()->{progress.dismiss();if(a.isFinishing())return;if(!message.isEmpty())toast(message);brand();});},"CreatorLogo").start();}
 void savePreset(){EditorProject.Clip c=a.creatorSelectedText();if(c==null){toast("Select the text or title you want to save");return;}EditText input=new EditText(a);input.setText(c.name);new AlertDialog.Builder(a).setTitle("Save my text preset").setView(input).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{String name=input.getText().toString().trim();if(name.isEmpty())return;try{EditorProject.Clip copy=c.copy();copy.start=0;copy.speed=1;copy.duration=copy.end=Math.max(200,a.creatorTextDuration());store.save(name,copy);toast("Saved · Text → Title library → My presets");}catch(Exception e){toast(e.getMessage());}}).show();}
 void starters(){AlertDialog[] chooser={null};LinearLayout p=column();p.addView(label("Start a separate draft with editable headings and a 40-second outline. Add your footage on the main video track; edit, move or delete each placeholder title. Your current draft is kept."));for(int i=0;i<EditorStarterProjects.NAMES.length;i++){int type=i;p.addView(button("＋ "+EditorStarterProjects.NAMES[i],()->new AlertDialog.Builder(a).setTitle("Create "+EditorStarterProjects.NAMES[type]+" project?").setMessage("A new draft will contain editable section titles and a closing card. It does not include stock footage or music.").setNegativeButton("Cancel",null).setPositiveButton("Create",(d,w)->{chooser[0].dismiss();a.creatorNew(EditorStarterProjects.create(type,store));}).show()));}chooser[0]=show("Starter projects",p);}
 void captions(){LinearLayout p=column();p.addView(label("Style existing text or create timed captions. Word timing is evenly estimated within each cue; no speech-recognition model is downloaded. Import SRT for your existing cue timings."));Spinner styles=select(p,"Caption style",EditorCaptionStyles.NAMES,1);EditorProject.Clip selected=a.creatorSelectedText();p.addView(button("Apply to selected text",()->{if(selected==null){toast("Select a text layer first");return;}a.creatorCheckpoint();EditorCaptionStyles.apply(selected,styles.getSelectedItemPosition());a.creatorChanged();toast("Caption style applied");}));p.addView(button("Apply to all plain text captions",()->{a.creatorCheckpoint();for(EditorProject.Caption c:a.creatorProject().captions)if(c.type.equals("Text")&&c.style.titleDesign==0)EditorCaptionStyles.apply(c.style,styles.getSelectedItemPosition());a.creatorChanged();toast("Plain captions updated; title designs kept");}));EditText script=field(p,"Type or paste spoken words", "",6000);Spinner length=select(p,"Caption span",new String[]{"10 seconds","20 seconds","30 seconds","60 seconds","To end of project"},2);p.addView(button("Create editable timed captions",()->{long duration=new long[]{10000,20000,30000,60000,Math.max(1000,a.creatorProject().duration()-a.creatorPosition())}[length.getSelectedItemPosition()];try{addCaptions(EditorCaptionStyles.typed(script.getText().toString(),a.creatorPosition(),duration,styles.getSelectedItemPosition(),a.creatorProject().textTracks()));}catch(Exception e){toast(e.getMessage());}}));p.addView(button("Import .srt captions",()->{a.getSharedPreferences("creator-library",0).edit().putInt("import-caption-style",styles.getSelectedItemPosition()).apply();a.creatorPick(561,"*/*");}));show("Animated captions",p);}
 private void addCaptions(ArrayList<EditorProject.Caption> cues){if(cues.isEmpty()){toast("Enter caption text first");return;}if(a.creatorProject().captions.size()+cues.size()>EditorProject.MAX_CLIPS){toast("This would exceed the 300-text-item project limit");return;}a.creatorCheckpoint();a.creatorProject().captions.addAll(cues);a.creatorChanged();toast(cues.size()+" editable captions added");}
 void importSrt(Uri uri){EditorProject target=a.creatorProject();long offset=a.creatorPosition();new Thread(()->{try{String text;try(InputStream in=a.getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Cannot open captions");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))!=-1){if(out.size()+n>1024*1024)throw new IOException("Choose an SRT file smaller than 1 MB");out.write(bytes,0,n);}text=out.toString("UTF-8");}ArrayList<EditorProject.Caption> cues=EditorCaptionStyles.srt(text,offset,a.getSharedPreferences("creator-library",0).getInt("import-caption-style",1),target.textTracks());a.runOnUiThread(()->{if(!a.isFinishing()&&a.creatorProject()==target)addCaptions(cues);});}catch(Exception e){a.runOnUiThread(()->toast("Caption import: "+e.getMessage()));}},"CaptionImport").start();}
 void safeGuides(){LinearLayout p=column();p.addView(label("Preview guides help keep titles away from platform buttons. Platform layouts vary; these are conservative estimates. Guides are never exported."));Spinner choice=select(p,"Social safe area",EditorSafeGuides.NAMES,a.creatorProject().safeGuide);choice.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){boolean first=true;public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> parent,View v,int pos,long id){if(first){first=false;return;}a.creatorCheckpoint();a.creatorProject().safeGuide=pos;a.creatorChanged();}});show("Safe-area guides",p);}
 void compare(){EditorProject p=a.creatorProject();if(p.overlays.isEmpty()){new AlertDialog.Builder(a).setTitle("Add your comparison footage").setMessage("Put the before shot on the main video track, then add the after shot as a video overlay. Reopen Before & after to choose a divider or animated reveal.").setPositiveButton("Add overlay",(d,w)->a.creatorOverlay()).setNegativeButton("Cancel",null).show();return;}LinearLayout panel=column();panel.addView(label("The selected overlay becomes a full-frame comparison over your main video. Match the two shots’ timing. Drag the divider slider live; the same mask is exported."));String[] names=new String[p.overlays.size()];for(int i=0;i<names.length;i++)names[i]=p.overlays.get(i).clip.name;Spinner layer=select(panel,"After / overlay layer",names,0),mode=select(panel,"Comparison layout",new String[]{"Off / normal overlay","Vertical divider","Horizontal divider","Animated reveal","Side by side"},1);TextView value=label("Divider · 50%");panel.addView(value);SeekBar split=new SeekBar(a);split.setMax(100);split.setProgress(50);panel.addView(split);Spinner duration=select(panel,"Reveal duration",new String[]{"0.5 seconds","1 second","2 seconds","3 seconds"},1);boolean[] applied={false};Runnable apply=()->{if(!applied[0]){a.creatorCheckpoint();applied[0]=true;}a.creatorSelectOverlay(layer.getSelectedItemPosition());EditorProject.Overlay o=p.overlays.get(layer.getSelectedItemPosition());o.clip.comparisonMode=mode.getSelectedItemPosition()==4?0:mode.getSelectedItemPosition();o.clip.comparisonSplit=split.getProgress()/100.;o.clip.comparisonDuration=new long[]{500,1000,2000,3000}[duration.getSelectedItemPosition()];if(o.clip.comparisonMode!=0){o.scale=1;o.x=o.y=0;o.alpha=1;o.clip.mask=0;}if(mode.getSelectedItemPosition()==4){EditorProject.Clip base=null;for(int k=0;k<p.clips.size();k++)if(o.at>=p.offset(k)&&o.at<p.offset(k)+p.clips.get(k).length()){base=p.clips.get(k);break;}if(base!=null){base.keys.clear();base.zoom=.5;base.panX=-.5;base.panY=0;}o.clip.keys.clear();o.clip.zoom=1;o.clip.panX=o.clip.panY=0;o.clip.mask=0;o.scale=.5;o.x=.5;o.y=0;}a.creatorRefresh();value.setText("Divider · "+split.getProgress()+"%");};split.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){a.creatorChanged();}public void onProgressChanged(SeekBar s,int n,boolean user){if(user)apply.run();}});panel.addView(button("Apply comparison",()->{apply.run();a.creatorChanged();toast("Comparison applied");}));show("Before & after",panel);}
 private void toast(String text){Toast.makeText(a,text==null?"Unable to complete this action":text,Toast.LENGTH_LONG).show();}
}
